function projectsFitler() {
    const buttons = document.querySelectorAll('.project_filter .project_filter_btn-js');
    const projects = document.querySelectorAll('.project_link-js');

    if(buttons) {
        buttons.forEach(btn => {
            btn.addEventListener('click', () => {
                buttons.forEach(b => b.classList.remove('active'));
                btn.classList.toggle('active');

                const filter = btn.getAttribute('data-filter');

                projects.forEach(p => {
                    if (filter === 'all' || p.classList.contains(filter)) {
                        p.classList.add('project_active-js');
                    } else {
                        p.classList.remove('project_active-js');
                    }
                });
            });
        });
    }
}
document.addEventListener('DOMContentLoaded', function() {
    projectsFitler();
});